CREATE TABLE IF NOT EXISTS gis_phase39115_geometry_inventory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), candidate_match_id uuid NOT NULL, geometry_source_table text, geometry_column text, geometry_type text, srid integer, geometry_present boolean NOT NULL DEFAULT false, geometry_valid boolean, provenance_status text NOT NULL, evidence_reference jsonb NOT NULL DEFAULT '{}'::jsonb, inventory_fingerprint text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS gis_phase39115_provenance_runs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), phase text NOT NULL, candidate_count integer NOT NULL DEFAULT 0, geometry_present_count integer NOT NULL DEFAULT 0, authoritative_inec_geometry_count integer NOT NULL DEFAULT 0, provenance_verified_count integer NOT NULL DEFAULT 0, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);